# 6. Archivo `main.js`

Crea el archivo:

```text
main.js
```

Contenido:

```js
const { app, BrowserWindow, ipcMain, dialog, shell } = require("electron");
const path = require("node:path");
const fs = require("node:fs/promises");

const isDev = Boolean(process.env.GOO_DEV);

function createWindow() {
  const win = new BrowserWindow({
    width: 1360,
    height: 860,
    minWidth: 980,
    minHeight: 640,
    backgroundColor: "#020617",
    autoHideMenuBar: true,
    title: "GlassOffice Beta",
    webPreferences: {
      preload: path.join(__dirname, "preload.js"),
      contextIsolation: true,
      nodeIntegration: false,
      sandbox: true
    }
  });

  win.loadFile(path.join(__dirname, "renderer", "index.html"));

  if (isDev) {
    win.webContents.openDevTools({ mode: "detach" });
  }

  win.webContents.setWindowOpenHandler(({ url }) => {
    if (url.startsWith("https:") || url.startsWith("http:")) {
      shell.openExternal(url);
    }
    return { action: "deny" };
  });
}

app.whenReady().then(() => {
  createWindow();

  app.on("activate", () => {
    if (BrowserWindow.getAllWindows().length === 0) {
      createWindow();
    }
  });
});

app.on("window-all-closed", () => {
  if (process.platform !== "darwin") {
    app.quit();
  }
});

ipcMain.handle("save-text", async (_event, payload) => {
  try {
    const { defaultPath, content, filters } = payload;

    const result = await dialog.showSaveDialog({
      defaultPath,
      filters: Array.isArray(filters) ? filters : []
    });

    if (result.canceled || !result.filePath) {
      return { ok: false };
    }

    await fs.writeFile(result.filePath, String(content), "utf8");

    return { ok: true, filePath: result.filePath };
  } catch (error) {
    return { ok: false, error: String(error) };
  }
});
```

