:root {
  --glass: rgba(255, 255, 255, 0.14);
  --line: rgba(255, 255, 255, 0.18);
  --text: #f8fafc;
}

* {
  box-sizing: border-box;
}

html,
body {
  height: 100%;
}

body {
  margin: 0;
  color: var(--text);
  font: 16px/1.5 system-ui, sans-serif;
  background:
    radial-gradient(1000px 700px at 10% 10%, rgba(14, 165, 233, 0.35), transparent),
    radial-gradient(900px 600px at 90% 30%, rgba(139, 92, 246, 0.35), transparent),
    radial-gradient(700px 500px at 50% 90%, rgba(34, 197, 94, 0.16), transparent),
    #020617;
}

header {
  position: sticky;
  top: 10px;
  z-index: 20;
  margin: 10px;
  padding: 10px 12px;
  border-radius: 16px;
  background: var(--glass);
  backdrop-filter: blur(18px) saturate(160%);
  border: 1px solid var(--line);
  display: flex;
  gap: 8px;
  align-items: center;
  flex-wrap: wrap;
}

.brand {
  display: flex;
  gap: 8px;
  align-items: center;
}

.badge {
  font-size: 0.75rem;
  padding: 3px 8px;
  border-radius: 999px;
  background: rgba(255, 255, 255, 0.12);
  border: 1px solid var(--line);
}

.spacer {
  flex: 1;
}

.tabs {
  display: flex;
  gap: 8px;
  flex-wrap: wrap;
}

button,
input,
select,
textarea {
  font: inherit;
  color: inherit;
}

button {
  padding: 8px 10px;
  border-radius: 12px;
  border: 1px solid var(--line);
  background: rgba(255, 255, 255, 0.08);
  cursor: pointer;
}

button:hover {
  background: rgba(255, 255, 255, 0.16);
}

.panel {
  margin: 10px;
  padding: 16px;
  border-radius: 20px;
  background: var(--glass);
  backdrop-filter: blur(20px) saturate(160%);
  border: 1px solid var(--line);
  min-height: 30vh;
}

#editor {
  min-height: 45vh;
  outline: none;
}

.hidden {
  display: none;
}

.grid {
  display: grid;
  grid-template-columns: 56px repeat(5, minmax(90px, 1fr));
  gap: 4px;
}

.cell {
  padding: 8px;
  border-radius: 10px;
  background: rgba(2, 6, 23, 0.25);
  border: 1px solid rgba(255, 255, 255, 0.12);
}

input.cell,
textarea.cell {
  width: 100%;
}

.wide {
  width: 100%;
  margin-bottom: 10px;
}

.small {
  font-size: 0.85rem;
  opacity: 0.78;
}

#status {
  margin-left: 8px;
}

.aiPanel {
  display: grid;
  grid-template-columns: 1fr auto;
  gap: 8px;
  margin-top: 10px;
}

#aiOut {
  white-space: pre-wrap;
  min-height: 1.5em;
}

@media (prefers-reduced-transparency: reduce) {
  header,
  .panel {
    backdrop-filter: none;
    background: rgba(2, 6, 23, 0.85);
  }
}
